import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  Container,
  Typography,
  Box,
  Paper,
  Skeleton,
  Fade,
  Breadcrumbs,
  Link
} from "@mui/material";
import {
  PrivacyTip,
  Home,
  NavigateNext,
  Security,
  Storage,
  Share
} from "@mui/icons-material";
import API_BASE_URL from "../../../../app/apiroutes";

const PrivacyPolicy = () => {
  const [policyData, setPolicyData] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPolicy();
  }, []);

  const fetchPolicy = async () => {
    try {
      const res = await axios.get(
        `${API_BASE_URL}/v1/api/information/privacy-policy`
      );
      if (res.data.success) {
        setPolicyData(res.data.data.value);
      }
    } catch (error) {
      console.error("Error fetching privacy policy:", error);
    } finally {
      setLoading(false);
    }
  };

  const highlights = [
    { icon: <Security />, text: "Your data is encrypted & secure" },
    { icon: <Storage />, text: "We store only necessary information" },
    { icon: <Share />, text: "No data sharing with third parties" }
  ];

  return (
    <Box sx={{ bgcolor: "#fafafa", minHeight: "100vh" }}>
      {/* Header */}
      <Box
        sx={{
          bgcolor: "#10b981",
          color: "white",
          py: { xs: 4, md: 6 },
          position: "relative",
          overflow: "hidden"
        }}
      >
        <Container maxWidth="lg">
          <Breadcrumbs
            separator={<NavigateNext fontSize="small" sx={{ color: "rgba(255,255,255,0.7)" }} />}
            sx={{ mb: 2 }}
          >
            <Link href="/" color="inherit" sx={{ display: "flex", alignItems: "center", textDecoration: "none" }}>
              <Home sx={{ fontSize: 18, mr: 0.5 }} />
              Home
            </Link>
            <Typography color="rgba(255,255,255,0.9)">Privacy Policy</Typography>
          </Breadcrumbs>
          
          <Typography
            variant="h2"
            sx={{
              fontSize: { xs: "1.75rem", md: "2.5rem" },
              fontWeight: 700,
              display: "flex",
              alignItems: "center",
              gap: 2
            }}
          >
            <PrivacyTip sx={{ fontSize: { xs: 30, md: 40 } }} />
            Privacy Policy
          </Typography>
        </Container>
      </Box>

      {/* Content */}
      <Container maxWidth="lg" sx={{ py: { xs: 4, md: 6 } }}>
        {/* Highlights */}
        <Fade in={!loading}>
          <Box sx={{ mb: 4 }}>
            <Box
              sx={{
                display: "flex",
                flexWrap: "wrap",
                gap: 2,
                justifyContent: { xs: "center", md: "flex-start" }
              }}
            >
              {highlights.map((item, idx) => (
                <Box
                  key={idx}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1,
                    bgcolor: "white",
                    px: 2,
                    py: 1,
                    borderRadius: 2,
                    boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
                    border: "1px solid #d1fae5"
                  }}
                >
                  <Box sx={{ color: "#10b981" }}>{item.icon}</Box>
                  <Typography variant="body2" fontWeight={500} color="#374151">
                    {item.text}
                  </Typography>
                </Box>
              ))}
            </Box>
          </Box>
        </Fade>

        {/* Main Content */}
        <Paper
          elevation={0}
          sx={{
            p: { xs: 3, md: 5 },
            borderRadius: 3,
            boxShadow: "0 4px 20px rgba(0,0,0,0.08)",
            border: "1px solid #e5e7eb"
          }}
        >
          {loading ? (
            <Box>
              <Skeleton variant="text" width="60%" height={40} sx={{ mb: 2 }} />
              <Skeleton variant="text" width="100%" height={20} sx={{ mb: 1 }} />
              <Skeleton variant="text" width="100%" height={20} sx={{ mb: 1 }} />
              <Skeleton variant="text" width="90%" height={20} sx={{ mb: 1 }} />
              <Skeleton variant="text" width="95%" height={20} />
            </Box>
          ) : (
            <Fade in={!loading}>
              <Box>
                <Typography
                  component="div"
                  sx={{
                    fontSize: { xs: "0.95rem", md: "1.05rem" },
                    lineHeight: 1.8,
                    color: "#4b5563",
                    "& h1, & h2, & h3": {
                      color: "#1f2937",
                      fontWeight: 600,
                      mt: 3,
                      mb: 2
                    },
                    "& p": { mb: 2 },
                    "& ul, & ol": { pl: 3, mb: 2 },
                    "& li": { mb: 1 }
                  }}
                  dangerouslySetInnerHTML={{ __html: policyData }}
                />
              </Box>
            </Fade>
          )}
        </Paper>

        {/* Contact Box */}
        <Box
          sx={{
            mt: 4,
            p: 3,
            bgcolor: "#ecfdf5",
            borderRadius: 2,
            border: "1px solid #a7f3d0",
            textAlign: "center"
          }}
        >
          <Typography variant="body1" color="#065f46" fontWeight={500}>
            Questions about your privacy? Contact our Data Protection Officer
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default PrivacyPolicy;