import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import useDocumentTitle from "../../../../hooks/useDocumentTitle";
import API_BASE_URL from "../../../../app/apiroutes";

import { Box, Typography, Card, CardContent, Grid } from "@mui/material";

import { CKEditor } from "@ckeditor/ckeditor5-react";
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";

const BusinessSettings = () => {
  useDocumentTitle("Business Settings");

  const [Business, setBusiness] = useState({
    about_us: "",
    cancellation_policy: "",
    privacy_policy: "",
    terms_and_conditions: ""
  });

  const [loading, setLoading] = useState(false);

  // store editor instances
  const editorsRef = useRef({});

  const fetchBusiness = async () => {
    try {
      const res = await axios.get(
        `${API_BASE_URL}/api/business-settings/settings-get`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("adminToken")}`
          }
        }
      );

      if (res.data.success && res.data.data) {
        const data = {
          about_us: res.data.data.about_us || "",
          cancellation_policy: res.data.data.cancellation_policy || "",
          privacy_policy: res.data.data.privacy_policy || "",
          terms_and_conditions: res.data.data.terms_and_conditions || ""
        };

        setBusiness(data);

        // inject data into editors
        Object.keys(data).forEach((key) => {
          if (editorsRef.current[key]) {
            editorsRef.current[key].setData(data[key]);
          }
        });
      }
    } catch (error) {
      console.error("Business Fetch Error:", error);
    }
  };

  useEffect(() => {
    fetchBusiness();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      setLoading(true);

      const res = await axios.post(
        `${API_BASE_URL}/api/business-settings/settings-update`,
        Business,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("adminToken")}`
          }
        }
      );

      if (res.data.success) {
        alert("Business Settings Updated Successfully");
      }
    } catch (error) {
      console.error("Business Update Error:", error);
    }

    setLoading(false);
  };

  const handleEditorChange = (name, editor) => {
    const data = editor.getData();

    setBusiness((prev) => ({
      ...prev,
      [name]: data
    }));
  };

  const editorConfig = {
    toolbar: [
      "heading",
      "|",
      "bold",
      "italic",
      "underline",
      "strikethrough",
      "|",
      "bulletedList",
      "numberedList",
      "|",
      "outdent",
      "indent",
      "|",
      "blockQuote",
      "insertTable",
      "|",
      "link",
      "imageUpload",
      "|",
      "undo",
      "redo"
    ],
    licenseKey: "GPL"
  };

  const sections = [
    { key: "about_us", title: "About Us" },
    { key: "privacy_policy", title: "Privacy Policy" },
    { key: "terms_and_conditions", title: "Terms & Conditions" },
    { key: "cancellation_policy", title: "Cancellation Policy" }
  ];

  return (
    <div className="container-fluid p-4">
      <Typography variant="h4" mb={3}>
        Business Settings
      </Typography>

      <form onSubmit={handleSubmit}>
        <Grid container spacing={3}>
          {sections.map((section) => (
            <Grid item xs={12} key={section.key}>
              <Card>
                <CardContent>
                  <Typography variant="h6" mb={2}>
                    {section.title}
                  </Typography>

                  <CKEditor
                    editor={ClassicEditor}
                    config={editorConfig}
                    onReady={(editor) => {
                      editorsRef.current[section.key] = editor;

                      // set initial data
                      if (Business[section.key]) {
                        editor.setData(Business[section.key]);
                      }
                    }}
                    onChange={(event, editor) =>
                      handleEditorChange(section.key, editor)
                    }
                  />
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Box mt={3}>
          <button
            type="submit"
            className="btn btn-success px-4"
            disabled={loading}
          >
            {loading ? "Saving..." : "Save All"}
          </button>
        </Box>
      </form>
    </div>
  );
};

export default BusinessSettings;