import React, { useEffect, useState } from 'react';
import Slider from "react-slick";
import {
  Box,
  Card,
  CardMedia,
  CardContent,
  Typography,
  Button,
  Chip
} from "@mui/material";

import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import { useNavigate } from 'react-router-dom';


const TourSlider = ({ tours, title }) => {
  const [slidesToShow, setSlidesToShow] = useState(3);
  const navigate = useNavigate();

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width <= 480) {
        setSlidesToShow(1);
      } else if (width <= 768) {
        setSlidesToShow(2);
      } else if (width >= 768 && width <= 1550) {
        setSlidesToShow(3);
      } else {
        setSlidesToShow(4);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  const settings = {
    dots: false,
    arrows: true,
    infinite: false,
    speed: 600,
    slidesToShow: slidesToShow,
    slidesToScroll: 1,
    responsive: [
      { breakpoint: 1200, settings: { slidesToShow: 3 } },
      { breakpoint: 900, settings: { slidesToShow: 2 } },
      { breakpoint: 600, settings: { slidesToShow: 1 } }
    ]
  };

  return (
    <Box sx={{ maxWidth: "1400px", mx: "auto", px: 2 }}>
      <Typography variant="h5" fontWeight={600} mb={2}>
        {title}
      </Typography>

      <Slider {...settings}>
        {tours.map((tour, index) => (
          <Box key={index} px={1}>
            <Card
              sx={{
                height: 260,
                borderRadius: 3,
                overflow: "hidden",
                position: "relative",
                boxShadow: "0 12px 30px rgba(0,0,0,0.2)"
              }}
            >
              <CardMedia
                component="img"
                image={tour.image}
                alt={tour.title}
                sx={{ height: "100%", objectFit: "cover" }}
              />

              <Chip
                label="Kashmir Holiday Planner"
                size="small"
                sx={{
                  position: "absolute",
                  top: 10,
                  right: 10,
                  bgcolor: "#6b82ebbf",
                  color: "#fff"
                }}
              />

              <CardContent
                sx={{
                  position: "absolute",
                  bottom: 0,
                  left: 0,
                  right: 0,
                  background:
                    "linear-gradient(to top, rgba(0,0,0,0.85), rgba(0,0,0,0.1))",
                  color: "#fff"
                }}
              >
                <Typography variant="h6">{tour.title}</Typography>

                <Box
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    mt: 1
                  }}
                >
                  <Typography fontWeight={700} color="#FFD700">
                    ₹{tour.price}/person
                  </Typography>

                  <Button
                    size="small"
                    variant="contained"
                    sx={{ bgcolor: "#0b3c5d", borderRadius: "20px" }}
                    onClick={() => navigate(`/tour-details/${tour.slug}`)}
                  >
                    Book Now
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default TourSlider;
