import React, { useState, useEffect } from 'react';
import {
  Container,
  Row,
  Col,
  Card,
  Badge,
  Button,
  Form,
  InputGroup,
  Alert
} from 'react-bootstrap';
import {
  Box,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Typography,
  Rating,
  Skeleton,
  useTheme,
  useMediaQuery
} from '@mui/material';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import FilterListIcon from '@mui/icons-material/FilterList';
import ClearAllIcon from '@mui/icons-material/ClearAll';
import 'bootstrap/dist/css/bootstrap.min.css';
import { useNavigate } from 'react-router-dom';
import API_BASE_URL from "../../../../app/apiroutes";

const Trips = () => {
  const [trips, setTrips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [sortBy, setSortBy] = useState('featured');
  const [searchTerm, setSearchTerm] = useState('');

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  // const isTablet = useMediaQuery(theme.breakpoints.down('md'));
  const navigate = useNavigate();
  // Fetch data from API
  useEffect(() => {
    const fetchTours = async () => {
      try {
        setLoading(true);
        const response = await fetch(`${API_BASE_URL}/v1/api/tour/tours`);

        if (!response.ok) {
          throw new Error('Failed to fetch tours');
        }

        const result = await response.json();

        if (result.success && result.data) {
          const transformedData = result.data.map(tour => ({
            id: tour.id,
            name: tour.tour_name,
            slug: tour.slug,
            image: tour.image,
            price: parseFloat(tour.price),
            discount: parseFloat(tour.discount) || 0,
            location: tour.slug || 'Unknown Location',
            days: tour.days || 'Duration not specified',
            rating: 4.5,
            reviews: Math.floor(Math.random() * 200) + 50
          }));
          setTrips(transformedData);
        } else {
          throw new Error('Invalid data format');
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchTours();
  }, []);

  const handleSortChange = (event) => {
    setSortBy(event.target.value);
  };

  const processedTrips = trips
    .filter(trip =>
      trip.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      trip.location.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => {
      switch (sortBy) {
        case 'price-low':
          return a.price - b.price;
        case 'price-high':
          return b.price - a.price;
        case 'alphabetical':
          return a.name.localeCompare(b.name);
        default:
          return 0;
      }
    });

  const getDiscountedPrice = (price, discount) => {
    if (!discount || discount === 0) return price;
    return price - (price * (discount / 100));
  };

  if (loading) {
    return (
      <Container className="py-3 py-md-5">
        <Box sx={{ width: '100%' }}>
          <Skeleton variant="rectangular" height={isMobile ? 120 : 200} className="mb-4 rounded" />
          <Row className="g-3">
            {[1, 2, 3].map((i) => (
              <Col xs={12} md={6} lg={4} key={i}>
                <Skeleton variant="rectangular" height={isMobile ? 400 : 350} className="rounded" />
              </Col>
            ))}
          </Row>
        </Box>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="py-5">
        <Alert variant="danger" className="m-2">
          <Alert.Heading className="h5">Error Loading Tours</Alert.Heading>
          <p className="mb-2 small">{error}</p>
          <Button
            variant="outline-danger"
            size="sm"
            onClick={() => window.location.reload()}
          >
            Retry
          </Button>
        </Alert>
      </Container>
    );
  }

  return (
    <div className="trips-wrapper bg-light min-vh-100">
      {/* Header Section - Mobile Optimized */}
      <div className="trips-header text-white py-4 py-md-5 mb-3 mb-md-4">
        <Container>
          <Row className="align-items-center g-3">
            <Col xs={12} lg={6}>
              <Typography
                variant={isMobile ? "h4" : "h2"}
                className="fw-bold mb-2 mb-md-3 text-center text-lg-start"
                sx={{ fontSize: isMobile ? '1.5rem !important' : '2.5rem !important' }}
              >
                Explore Amazing Trips
              </Typography>
              <Typography
                variant={isMobile ? "body2" : "h6"}
                className="opacity-75 text-center text-lg-start"
                sx={{ fontSize: isMobile ? '0.875rem !important' : '1.25rem !important' }}
              >
                Find your perfect adventure from our curated collection of {trips.length} tours
              </Typography>
            </Col>
            <Col xs={12} lg={6}>
              <InputGroup className="shadow-sm">
                <Form.Control
                  placeholder="Search destinations..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="border-0 py-2 py-md-3"
                  style={{ fontSize: isMobile ? '16px' : 'inherit' }} // Prevent zoom on iOS
                />
                <Button variant="light" className="border-0 px-3 px-md-4">
                  <FilterListIcon fontSize={isMobile ? "small" : "medium"} />
                </Button>
              </InputGroup>
            </Col>
          </Row>
        </Container>
      </div>

      <Container className="pb-4 pb-md-5 px-3 px-md-4">
        {/* Controls Section - Stack on mobile */}
        <Row className="mb-3 mb-md-4 align-items-center g-2">
          <Col xs={12} md={6} className="text-center text-md-start">
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{ fontSize: isMobile ? '0.8rem' : '0.875rem' }}
            >
              Showing {processedTrips.length} of {trips.length} tours
            </Typography>
          </Col>
          <Col xs={12} md={6}>
            <Box sx={{
              width: '100%',
              maxWidth: isMobile ? '100%' : 200,
              mt: isMobile ? 1 : 0
            }}>
              <FormControl fullWidth size="small">
                <InputLabel id="sort-select-label" sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}>
                  <FilterListIcon fontSize="small" className="me-1" />
                  Sort By
                </InputLabel>
                <Select
                  labelId="sort-select-label"
                  id="sort-select"
                  value={sortBy}
                  label="Sort By"
                  onChange={handleSortChange}
                  sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}
                >
                  <MenuItem value="featured" sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}>Featured</MenuItem>
                  <MenuItem value="price-low" sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}>Price: Low to High</MenuItem>
                  <MenuItem value="price-high" sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}>Price: High to Low</MenuItem>
                  <MenuItem value="alphabetical" sx={{ fontSize: isMobile ? '0.875rem' : '1rem' }}>Alphabetical (A-Z)</MenuItem>
                </Select>
              </FormControl>
            </Box>

            {searchTerm && (
              <Button
                variant="outline-secondary"
                size="sm"
                onClick={() => setSearchTerm('')}
                className="d-flex align-items-center ms-auto ms-md-2 mt-2 mt-md-0"
              >
                <ClearAllIcon fontSize="small" className="me-1" />
                Clear
              </Button>
            )}
          </Col>
        </Row>

        {/* Trips Grid - Full width on mobile */}
        {processedTrips.length === 0 ? (
          <Box className="text-center py-5">
            <Typography variant={isMobile ? "h6" : "h5"} color="text.secondary" className="mb-2">
              No tours found
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Try adjusting your search or filters
            </Typography>
          </Box>
        ) : (
          <Row className="g-3 g-md-4">
            {processedTrips.map((trip) => (
              <Col key={trip.id} xs={12} md={6} lg={4}>
                <Card className="h-100 shadow-sm border-0 overflow-hidden hover-shadow transition-all">
                  {/* Image Container - Fixed aspect ratio */}
                  <div className="position-relative" style={{
                    height: isMobile ? '180px' : '240px',
                    overflow: 'hidden'
                  }}>
                    <Card.Img
                      variant="top"
                      src={trip.image}
                      alt={trip.name}
                      style={{
                        height: '100%',
                        width: '100%',
                        objectFit: 'cover',
                        objectPosition: 'center'
                      }}
                      onError={(e) => {
                        e.target.src = 'https://via.placeholder.com/500x300?text=No+Image';
                      }}
                    />
                    {trip.discount > 0 && (
                      <Badge
                        bg="danger"
                        className="position-absolute top-0 end-0 m-2 m-md-3 px-2 px-md-3 py-1 py-md-2"
                        style={{ fontSize: isMobile ? '0.75rem' : '0.875rem' }}
                      >
                        -{trip.discount}%
                      </Badge>
                    )}
                    <div className="position-absolute bottom-0 start-0 m-2 m-md-3">
                      <Chip
                        icon={<LocationOnIcon fontSize="small" />}
                        label={trip.location}
                        size="small"
                        sx={{
                          backgroundColor: 'rgba(255,255,255,0.95)',
                          fontWeight: 600,
                          fontSize: isMobile ? '0.75rem' : '0.875rem',
                          height: isMobile ? '28px' : '32px',
                          backdropFilter: 'blur(4px)'
                        }}
                      />
                    </div>
                  </div>

                  <Card.Body className="p-3 p-md-4">
                    {/* Title & Rating - Stack on very small screens */}
                    <div className="d-flex flex-column flex-sm-row justify-content-between align-items-start mb-2 gap-2">
                      <Typography
                        variant="h6"
                        className="fw-bold mb-0 w-100"
                        sx={{
                          fontSize: isMobile ? '1rem !important' : '1.25rem !important',
                          lineHeight: 1.3
                        }}
                      >
                        {trip.name}
                      </Typography>
                      <Box className="d-flex align-items-center flex-shrink-0">
                        <Rating
                          value={trip.rating}
                          precision={0.1}
                          size="small"
                          readOnly
                        />
                        <Typography
                          variant="caption"
                          className="ms-1 text-muted"
                          sx={{ fontSize: isMobile ? '0.7rem' : '0.75rem', whiteSpace: 'nowrap' }}
                        >
                          ({trip.reviews})
                        </Typography>
                      </Box>
                    </div>

                    {/* Details */}
                    <div className="mb-2 mb-md-3 text-muted">
                      <Box className="d-flex align-items-center mb-1 mb-md-2">
                        <AccessTimeIcon
                          fontSize="small"
                          className="me-2"
                          sx={{ fontSize: isMobile ? '1rem' : '1.25rem' }}
                        />
                        <Typography
                          variant="body2"
                          sx={{ fontSize: isMobile ? '0.8rem' : '0.875rem' }}
                        >
                          {trip.days}
                        </Typography>
                      </Box>
                    </div>

                    {/* Price & Action - Stack on mobile */}
                    <div className="d-flex flex-column flex-sm-row justify-content-between align-items-start align-items-sm-center mt-auto pt-2 pt-md-3 border-top gap-2">
                      <div>
                        {trip.discount > 0 ? (
                          <div>
                            <Typography
                              variant="caption"
                              className="text-decoration-line-through text-muted d-block"
                              sx={{ fontSize: isMobile ? '0.7rem' : '0.75rem' }}
                            >
                              ${trip.price.toFixed(2)}
                            </Typography>
                            <Typography
                              variant="h6"
                              className="fw-bold text-success mb-0"
                              sx={{ fontSize: isMobile ? '1.1rem !important' : '1.25rem !important' }}
                            >
                              ${getDiscountedPrice(trip.price, trip.discount).toFixed(2)}
                            </Typography>
                          </div>
                        ) : (
                          <Typography
                            variant="h6"
                            className="fw-bold text-primary mb-0 d-flex align-items-center"
                            sx={{ fontSize: isMobile ? '1.1rem !important' : '1.25rem !important' }}
                          >
                            <AttachMoneyIcon sx={{ fontSize: isMobile ? '1.1rem' : '1.25rem' }} />
                            {trip.price.toFixed(2)}
                          </Typography>
                        )}
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          sx={{ fontSize: isMobile ? '0.7rem' : '0.75rem' }}
                        >
                          per person
                        </Typography>
                      </div>

                      <Button
                        variant="primary"
                        className="fw-semibold w-100 w-sm-auto"
                        size={isMobile ? "sm" : "md"}
                        style={{
                          borderRadius: '20px',
                          fontSize: isMobile ? '0.875rem' : '1rem',
                          padding: isMobile ? '6px 16px' : '8px 24px'
                        }}
                        onClick={() => navigate(`/tour-details/${trip.slug}`)}
                      >
                        Book Now
                      </Button>
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>
        )}
      </Container>

      {/* Custom Styles */}
      <style jsx global>{`
        .trips-wrapper {
          font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        }
        .trips-header {
          background: linear-gradient(319deg, #299ea5a1 0%, #c38323a6 100%) !important;
        }
        .hover-shadow {
          transition: all 0.3s ease;
        }
        .hover-shadow:hover {
          transform: translateY(-5px);
          box-shadow: 0 1rem 3rem rgba(0,0,0,.175) !important;
        }
        @media (max-width: 576px) {
          .hover-shadow:hover {
            transform: translateY(-3px);
          }
        }
        /* Prevent horizontal scroll */
        .row {
          margin-left: 0;
          margin-right: 0;
        }
        .container {
          padding-left: 16px;
          padding-right: 16px;
        }
        @media (min-width: 768px) {
          .container {
            padding-left: 24px;
            padding-right: 24px;
          }
        }
      `}</style>
    </div>
  );
};

export default Trips;