import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Chip,
  IconButton,
  Fade,
  Backdrop,
  useTheme,
  useMediaQuery
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import "bootstrap/dist/css/bootstrap.min.css";
import API_BASE_URL from "../../../../app/apiroutes";

const Gallery = () => {
  const [tours, setTours] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTour, setSelectedTour] = useState(null);
  const [hoveredId, setHoveredId] = useState(null);
   const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  useEffect(() => {
    const fetchTours = async () => {
      try {
        setLoading(true);
        const response = await fetch(`${API_BASE_URL}/v1/api/tour/tours`);

        if (!response.ok) {
          throw new Error("Failed to fetch tours");
        }

        const result = await response.json();

        if (result.success && result.data) {
          setTours(result.data);
        } else {
          throw new Error("Invalid data format");
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchTours();
  }, []);

  const getDiscountedPrice = (price, discount) => {
    if (!discount || discount === 0) return parseFloat(price);
    return parseFloat(price) - (parseFloat(price) * (parseFloat(discount) / 100));
  };

  if (loading) {
    return (
      <div className="container py-5">
        <div className="row g-4">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="col-12 col-md-6 col-lg-4">
              <div
                className="card border-0 shadow-sm"
                style={{
                  height: "400px",
                  background: "linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%)",
                  backgroundSize: "200% 100%",
                  animation: "shimmer 1.5s infinite"
                }}
              />
            </div>
          ))}
        </div>
        <style>{`
          @keyframes shimmer {
            0% { background-position: 200% 0; }
            100% { background-position: -200% 0; }
          }
        `}</style>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-vh-100 d-flex align-items-center justify-content-center">
        <div className="text-center">
          <h4 className="text-danger mb-3">Something went wrong</h4>
          <button
            className="btn btn-outline-primary rounded-pill px-4"
            onClick={() => window.location.reload()}
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="gallery-page bg-light min-vh-100">
      {/* Cards Grid */}
      <div className="container pb-5 mt-4">
        <div className="row g-4">
          {tours.map((tour, index) => (
            <div
              key={tour.id}
              className="col-12 col-md-6 col-lg-4"
              style={{ animationDelay: `${index * 0.1}s` }}
            >
              <div className="card h-100 border-0 shadow-sm overflow-hidden tour-card"
                onMouseEnter={() => setHoveredId(tour.id)}
                onMouseLeave={() => setHoveredId(null)}
                onClick={() => setSelectedTour(tour)}>
                {/* Image Section */}
                <div className="position-relative overflow-hidden" style={{ height: "200px" }}>
                  <img
                    src={tour.image}
                    alt={tour.tour_name}
                    className="w-100 h-100"
                    style={{
                      objectFit: "cover",
                      transition: "transform 0.6s ease",
                      transform: hoveredId === tour.id ? "scale(1.1)" : "scale(1)"
                    }}
                    onError={(e) => {
                      e.target.src = "https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=600&h=400&fit=crop";
                    }}
                  />

                  {/* Hover Overlay */}
                  <div
                    className="position-absolute top-0 start-0 w-100 h-100 d-flex align-items-center justify-content-center"
                    style={{
                      backgroundColor: "rgba(0,0,0,0.4)",
                      opacity: hoveredId === tour.id ? 1 : 0,
                      transition: "opacity 0.3s ease",
                      cursor: "pointer"
                    }}
                  >
                    <span className="btn btn-light rounded-pill px-4 fw-semibold">
                      View Details <ArrowForwardIcon className="ms-1" fontSize="small" />
                    </span>
                  </div>

                  {/* Location Chip */}
                  <div className="position-absolute bottom-0 start-0 m-3">
                    <Chip
                      icon={<LocationOnIcon fontSize="small" />}
                      label={tour.slug}
                      size="small"
                      className="bg-white text-dark fw-semibold"
                      style={{ backdropFilter: "blur(10px)" }}
                    />
                  </div>
                </div>


              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Detail Modal */}
      <Backdrop
        open={!!selectedTour}
        onClick={() => setSelectedTour(null)}
        sx={{ zIndex: 1300, backgroundColor: "rgba(0,0,0,0.8)" }}
      >
        <Fade in={!!selectedTour}>
          <Box
            className="position-relative bg-white rounded-4 overflow-hidden"
            sx={{
              maxWidth: "900px",
              width: "90%",
              maxHeight: "90vh",
              overflowY: "auto"
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {selectedTour && (
              <>
                {/* Close Button */}
                <IconButton
                  onClick={() => setSelectedTour(null)}
                  className="position-absolute top-0 end-0 m-3 bg-white shadow-sm"
                  sx={{ zIndex: 10 }}
                >
                  <CloseIcon />
                </IconButton>

                {/* Modal Image */}
                <div  style={{ fontSize: isMobile ? "0.875rem" : "1rem" }}>
                  <img
                    src={selectedTour.image}
                    alt={selectedTour.tour_name}
                    className="w-100 h-100"
                    style={{ objectFit: "cover" }}
                  />
                </div>
              </>
            )}
          </Box>
        </Fade>
      </Backdrop>

      {/* Custom Styles */}
      <style jsx global>{`
        .gallery-page {
          font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        }
        
        .tour-card {
          transition: all 0.3s ease;
          border-radius: 16px;
        }
        
        .tour-card:hover {
          transform: translateY(-8px);
          box-shadow: 0 20px 40px rgba(0,0,0,0.1) !important;
        }
        
        .col-12 {
          animation: fadeInUp 0.6s ease forwards;
          opacity: 0;
        }
        
        @keyframes fadeInUp {
          from {
            opacity: 0;
            transform: translateY(30px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        
        .rounded-4 {
          border-radius: 20px !important;
        }
        
        /* Smooth scrollbar for modal */
        ::-webkit-scrollbar {
          width: 8px;
        }
        ::-webkit-scrollbar-track {
          background: #f1f1f1;
        }
        ::-webkit-scrollbar-thumb {
          background: #888;
          border-radius: 4px;
        }
      `}</style>
    </div>
  );
};

export default Gallery;