import { Route, Routes } from 'react-router-dom';
import UserLayout from '../features/user/components/UserLayout/UserLayout';

import Home from '../features/user/pages/Home/Home';
import About from '../features/user/pages/About/About';
import Trips from '../features/user/pages/Trips/Trips';
import TourDetails from '../features/user/pages/TourDetails/TourDetails';
import Gallery from '../features/user/pages/Gallery/Gallery';
import Contact from '../features/user/pages/Contact/Contact';
import BookingSuccess from '../features/user/pages/TourDetails/BookingSuccess';
import TermsConditions from '../features/user/pages/About/TermsConditions';
import PrivacyPolicy from '../features/user/pages/About/PrivacyPolicy';
import CancellationPolicy from '../features/user/pages/About/CancellationPolicy';

const UserRoutes = () => (
  <Routes>
  <Route element={<UserLayout />} >
    <Route path="/" element={<Home />} />
    <Route path="/about" element={<About />} />
    <Route path="/trips" element={<Trips />} />
    <Route path="/tour-details/:id" element={<TourDetails />} />
    <Route path="/booking-success" element={<BookingSuccess />} />
    <Route path="/gallery" element={<Gallery />} />
    <Route path="/contact" element={<Contact />} />
    <Route path="/cancellation-policy" element={<CancellationPolicy />} />
    <Route path="/privacy-policy" element={<PrivacyPolicy />} />
    <Route path="/terms-and-conditions" element={<TermsConditions />} />
    </Route>
  </Routes>
);

export default UserRoutes;
