import React, { useEffect, useState } from 'react';
import {
  Box, Grid, TextField, Button, Typography, Paper,
  IconButton, Divider, Card, CardContent, Avatar
} from '@mui/material';
import { Add, Delete } from '@mui/icons-material';
import axios from 'axios';
import { useNavigate, useParams } from 'react-router-dom';
import useDocumentTitle from '../../../../hooks/useDocumentTitle';
import { CKEditor } from '@ckeditor/ckeditor5-react';
import ClassicEditor from '@ckeditor/ckeditor5-build-classic';
import API_BASE_URL from "../../../../app/apiroutes";

const UpdateTour = () => {
  useDocumentTitle('Update Tour');
  const navigate = useNavigate();
  const { id } = useParams();

  // ================= BASIC FORM =================
  const [form, setForm] = useState({
    tour_name: '',
    days: '',
    price: '',
    discount: '',
    description: ''
  });

  // ================= ARRAY STATES =================
  const [includes, setIncludes] = useState(['']);
  const [excludes, setExcludes] = useState(['']);
  const [locations, setLocations] = useState(['']);
  const [itinerary, setItinerary] = useState([
    { day: '', title: '', description: '' }
  ]);
  const [pricingRows, setPricingRows] = useState([
    { min: '', max: '', price: '' }
  ]);

  // ================= IMAGES =================
  const [mainImage, setMainImage] = useState(null);
  const [mainImagePreview, setMainImagePreview] = useState(null);
  const [images, setImages] = useState([]); // old + new

  // ================= LOAD DATA =================
  useEffect(() => {
    const fetchTour = async () => {
      const token = localStorage.getItem('adminToken');
      const res = await axios.get(`${API_BASE_URL}/api/tour/edit/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          }
        }
      );

      const data = res.data.data;

      setForm({
        tour_name: data.tour_name,
        days: data.days,
        price: data.price,
        discount: data.discount,
        description: data.description
      });

      setIncludes(data.include || ['']);
      setExcludes(data.exclude || ['']);
      setLocations(data.locations || ['']);
      setItinerary(data.itinerary || []);
      setPricingRows(data.pricing_slabs || []);
      setMainImagePreview(data.image);

      // existing images
      setImages(
        data.images.map(url => ({
          preview: url,
          old: true
        }))
      );
    };

    fetchTour();
  }, [id]);

  // ================= HANDLERS =================
  const handleInputChange = e =>
    setForm({ ...form, [e.target.name]: e.target.value });

   const handleEditorChange = (event, editor) => {
    const data = editor.getData();
    setForm(prev => ({
      ...prev,
      description: data
    }));
  };

  const handleDynamicChange = (setter, index, field, value) => {
    setter(prev => {
      const data = [...prev];
      data[index][field] = value;
      return data;
    });
  };

  const addItem = (setter, value) =>
    setter(prev => [...prev, value]);

  const removeItem = (setter, index) =>
    setter(prev => prev.filter((_, i) => i !== index));

  const handlePricingChange = (index, field, value) => {
    const rows = [...pricingRows];
    rows[index][field] = value; setPricingRows(rows);
  };

  const addRow = () => setPricingRows([...pricingRows, { min: '', max: '', price: '' }]);
  const removeRow = (index) => setPricingRows(pricingRows.filter((_, i) => i !== index));
  const handleImageUpload = e => {
    const files = Array.from(e.target.files).map(file => ({
      file,
      preview: URL.createObjectURL(file),
      old: false
    }));
    setImages(prev => [...prev, ...files]);
  };

  const handleSubmit = async () => {
    const token = localStorage.getItem('adminToken');
    const formData = new FormData();

    Object.keys(form).forEach(k => formData.append(k, form[k]));

    formData.append('includes', JSON.stringify(includes));
    formData.append('excludes', JSON.stringify(excludes));
    formData.append('locations', JSON.stringify(locations));
    formData.append('itinerary', JSON.stringify(itinerary));
    formData.append('pricing_slabs', JSON.stringify(pricingRows));

    if (mainImage) formData.append('image', mainImage);

    images.forEach(img => {
      if (!img.old) formData.append('images[]', img.file);
    });

    await axios.post(`${API_BASE_URL}/api/tour/update/${id}`,
      formData,
      {
        headers: { Authorization: `Bearer ${token}`}
      }
    );

    alert('Tour Updated Successfully ✅');
    navigate('/admin/tour-list');
  };
  const mainImageSrc = mainImage
    ? URL.createObjectURL(mainImage)
    : mainImagePreview;
  // ================= UI =================
  return (
    <Box sx={{ p: 3, maxWidth: 1200, mx: 'auto' }}>
      <Typography variant="h4" fontWeight={700} mb={3}>
        Update Tour
      </Typography>

      <Paper sx={{ p: 4 }}>

        {/* BASIC INFO */}
        <Grid container spacing={3}>
          {['tour_name', 'days', 'price', 'discount'].map(field => (
            <Grid item xs={12} md={3} key={field}>
              <TextField
                label={field.replace('_', ' ').toUpperCase()}
                name={field}
                value={form[field]}
                onChange={handleInputChange}
                fullWidth
              />
            </Grid>
          ))}
        </Grid>

        <Divider sx={{ my: 4 }} />

        {/* MAIN IMAGE */}
        <Typography variant="h6">Main Image</Typography>
        <Button component="label" variant="outlined">
          Change Image
          <input hidden type="file" onChange={e => setMainImage(e.target.files[0])} />
        </Button>


        {mainImageSrc && (
          <Avatar
            src={mainImageSrc}
            variant="rounded"
            sx={{ width: 140, height: 100, mt: 2 }}
          />
        )}

        <Divider sx={{ my: 4 }} />

        {/* MULTI IMAGES */}
        <Typography variant="h6">Tour Images</Typography>
        <Button component="label" variant="outlined">
          Upload Images
          <input hidden multiple type="file" onChange={handleImageUpload} />
        </Button>

        <Box sx={{ display: 'flex', gap: 2, mt: 2, flexWrap: 'wrap' }}>
          {images.map((img, i) => (
            <Box key={i} position="relative">
              <Avatar
                src={img.preview}
                variant="rounded"
                sx={{ width: 100, height: 80 }}
              />
              <IconButton
                color="error"
                size="small"
                sx={{ position: 'absolute', top: -8, right: -8 }}
                onClick={() => removeItem(setImages, i)}
              >
                <Delete />
              </IconButton>
            </Box>
          ))}
        </Box>

        <Divider sx={{ my: 4 }} />

        <Box sx={{ mb: 4 }}>
                    <CKEditor
                      editor={ClassicEditor}
                      data={form.description}
                      onChange={handleEditorChange}
                      config={{
                        toolbar: ['heading', '|', 'fontFamily', 'fontSize', '|', 'bold', 'italic', 'underline', 'strikethrough', '|', 'bulletedList', 'numberedList', '|', 'outdent', 'indent', '|', 'blockQuote', 'insertTable', '|', 'link', 'imageUpload', '|', 'undo', 'redo'],
                        fontFamily: {
                          options: [
                            'default',
                            'Arial, Helvetica, sans-serif',
                            'Courier New, Courier, monospace',
                            'Georgia, serif',
                            'Tahoma, Geneva, sans-serif',
                            'Times New Roman, Times, serif',
                            'Verdana, Geneva, sans-serif'
                          ],
                          supportAllValues: true
                        },
                        fontSize: {
                          options: [
                            10, 12, 14, 'default', 18, 20, 22, 24, 26, 28, 36
                          ],
                          supportAllValues: true
                        },
                        height: 300,
                        licenseKey: 'GPL'
                      }}
                    />
                  </Box>

        <Divider sx={{ my: 4 }} />

        {/* INCLUDE / EXCLUDE */}
        {[['Includes', includes, setIncludes], ['Excludes', excludes, setExcludes], ['Booking Locations', locations, setLocations]]
          .map(([label, state, setter]) => (
            <Box key={label} mb={3}>
              <Typography variant="h6">{label}</Typography>
              {state.map((v, i) => (
                <Box key={i} display="flex" gap={1} mt={1}>
                  <TextField
                    fullWidth
                    value={v}
                    onChange={e => {
                      const d = [...state];
                      d[i] = e.target.value;
                      setter(d);
                    }}
                  />
                  <IconButton color="error" onClick={() => removeItem(setter, i)}>
                    <Delete />
                  </IconButton>
                </Box>
              ))}
              <Button startIcon={<Add />} onClick={() => addItem(setter, '')}>
                Add {label}
              </Button>
            </Box>
          ))}

        <Divider sx={{ my: 4 }} />
        {/* ITINERARY */}
        <Typography variant="h6">Day-wise Itinerary</Typography>
        {itinerary.map((item, i) => (
          <Card key={i} sx={{ mt: 2 }}>
            <CardContent>
              <Grid container spacing={2}>
                <Grid item xs={12} md={2}>
                  <TextField label="Day" value={item.day}
                    onChange={(e) => handleDynamicChange(setItinerary, i, 'day', e.target.value)} />
                </Grid>
                <Grid item xs={12} md={4}>
                  <TextField label="Title" fullWidth value={item.title}
                    onChange={(e) => handleDynamicChange(setItinerary, i, 'title', e.target.value)} />
                </Grid>
                <Grid item xs={12} md={5}>
                  <TextField label="Description" fullWidth value={item.description}
                    onChange={(e) => handleDynamicChange(setItinerary, i, 'description', e.target.value)} />
                </Grid>
                <Grid item xs={12} md={1}>
                  {itinerary.length > 1 && (
                    <IconButton color="error" onClick={() => removeItem(setItinerary, i)}>
                      <Delete />
                    </IconButton>
                  )}
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        ))}
        <Button startIcon={<Add />} onClick={() => addItem(setItinerary, { day: '', title: '', description: '' })}>
          Add Day
        </Button>

        <Divider sx={{ my: 4 }} />
        <Typography variant="h6" mb={2}> Pricing Slabs (Min - Max - Price) </Typography>
        {pricingRows.map((row, index) => (
          <Card key={index} sx={{ mb: 2 }}>
            <CardContent>
              <Grid container spacing={2} alignItems="center">
                <Grid item xs={12} md={3}>
                  <TextField label="Min" type="number" value={row.min} onChange={(e) => handlePricingChange(index, 'min', e.target.value)} fullWidth /> </Grid>
                <Grid item xs={12} md={3}>
                  <TextField label="Max" type="number" value={row.max} onChange={(e) => handlePricingChange(index, 'max', e.target.value)} fullWidth /> </Grid>
                <Grid item xs={12} md={3}>
                  <TextField label="Price" type="number" value={row.price} onChange={(e) => handlePricingChange(index, 'price', e.target.value)} fullWidth /> </Grid>
                <Grid item xs={12} md={3} textAlign="center"> {pricingRows.length > 1 && (<IconButton color="error" onClick={() => removeRow(index)}> <Delete /> </IconButton>)}
                </Grid>
              </Grid>
            </CardContent>
          </Card>))}
        <Button startIcon={<Add />} variant="outlined" onClick={addRow}> Add More Pricing </Button>

        <Divider sx={{ my: 4 }} />
        {/* SAVE */}
        <Box textAlign="right">
          <Button size="large" variant="contained" onClick={handleSubmit}>
            Update Tour
          </Button>
        </Box>

      </Paper>
    </Box>
  );
};

export default UpdateTour;