import React, { useState, useEffect } from 'react';
import { useNavigate} from 'react-router-dom';
import { API_ENDPOINTS } from "../../../app/apiroutes";
import {
    FaShoppingCart,
    FaLock,
    FaEnvelope,
    FaEye,
    FaEyeSlash
} from 'react-icons/fa';
import './Auth.css';

const Login = () => {

    const token = localStorage.getItem("adminToken");
    const navigate = useNavigate();
    const [credentials, setCredentials] = useState({
        email: '',
        password: '',
        rememberMe: false
    });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [loginAttempts, setLoginAttempts] = useState(0);

    useEffect(() => {
        const token = localStorage.getItem("adminToken");

        if (token && window.location.pathname !== "/admin") {
            navigate("/admin/dashboard", { replace: true });
        }
        const savedEmail = localStorage.getItem('rememberedEmail');
        if (savedEmail) {
            setCredentials(prev => ({   
                ...prev,
                email: savedEmail,
                rememberMe: true
            }));
        }
    }, [navigate]);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target; setCredentials(prev => ({ ...prev, [name]: type === 'checkbox' ? checked : value }));
        setError('');
    };

    const validateForm = () => {
        if (!credentials.email.trim()) {
            setError('Email is required');
            return false;
        }

        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(credentials.email)) {
            setError('Please enter a valid email address');
            return false;
        }

        if (!credentials.password) {
            setError('Password is required');
            return false;
        }

        if (credentials.password.length < 6) {
            setError('Password must be at least 6 characters');
            return false;
        }

        return true;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!validateForm()) return;

        if (loginAttempts >= 3) {
            setError('Too many failed attempts. Please try again later.');
            return;
        }

        setLoading(true);
        setError('');
        try {
            const response = await fetch(API_ENDPOINTS.ADMIN_LOGIN, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email: credentials.email,
                    password: credentials.password,
                }),
            });
            const data = await response.json();
            if (!response.ok || !data.success) {
                throw new Error(data.message || 'Login failed');
            }
            localStorage.setItem('adminToken', data.token);
            localStorage.setItem('adminUser', JSON.stringify(data.admin));
            if (credentials.rememberMe) {
                localStorage.setItem('rememberedEmail', credentials.email);
            } else {
                localStorage.removeItem('rememberedEmail');
            }
            setLoginAttempts(0);
            navigate('/admin/login', { replace: true });

        } catch (err) {
            setLoginAttempts(prev => prev + 1);
            setError(err.message || 'Invalid email or password');
        } finally {
            setLoading(false);
        }
    };


    const handleForgotPassword = () => {
        if (!credentials.email) {
            setError('Please enter your email address first');
            return;
        }
        setError(`Password reset link would be sent to ${credentials.email} in a real application`);
    };

    return (
        <div className="auth-container">
            <div className="auth-card">
                {/* Header */}
                <div className="auth-header">
                    <div className="auth-logo">
                        <FaShoppingCart className="logo-icon" />
                        <div className="logo-text">
                            <h1>E-Shop</h1>
                            <span className="logo-subtitle">Admin Dashboard</span>
                        </div>
                    </div>
                    <p className="auth-description">
                        Sign in to access the admin panel
                    </p>
                </div>

                {/* Error Message */}
                {error && (
                    <div className={`auth-message ${error.includes('would be') ? 'info' : 'error'}`}>
                        <div className="message-content">
                            {error.includes('Invalid') && <FaLock />}
                            {error}
                        </div>
                    </div>
                )}

                {/* Login Form */}
                <form onSubmit={handleSubmit} className="auth-form">
                    <div className="form-group">
                        <label className="form-label">
                            <FaEnvelope className="label-icon" />
                            Email Address
                        </label>
                        <input
                            type="email"
                            name="email"
                            value={credentials.email}
                            onChange={handleChange}
                            placeholder="admin@ecommerce.com"
                            className="form-input"
                            required
                            disabled={loading}
                        />
                    </div>

                    <div className="form-group">
                        <label className="form-label">
                            <FaLock className="label-icon" />
                            Password
                        </label>
                        <div className="password-input">
                            <input
                                type={showPassword ? "text" : "password"}
                                name="password"
                                value={credentials.password}
                                onChange={handleChange}
                                placeholder="Enter your password"
                                className="form-input"
                                required
                                disabled={loading}
                            />
                            <button
                                type="button"
                                className="password-toggle"
                                onClick={() => setShowPassword(!showPassword)}
                                disabled={loading}
                            >
                                {showPassword ? <FaEyeSlash /> : <FaEye />}
                            </button>
                        </div>
                    </div>

                    <div className="form-options">
                        <label className="checkbox-container">
                            <input
                                type="checkbox"
                                name="rememberMe"
                                checked={credentials.rememberMe}
                                onChange={handleChange}
                                disabled={loading}
                            />
                            <span className="checkmark"></span>
                            Remember me
                        </label>
                        <button
                            type="button"
                            className="forgot-link"
                            onClick={handleForgotPassword}
                            disabled={loading}
                        >
                            Forgot Password?
                        </button>
                    </div>

                    <button
                        type="submit"
                        className="auth-btn"
                        disabled={loading || loginAttempts >= 3}
                    >
                        {loading ? (
                            <>
                                <span className="spinner"></span>
                                Signing in...
                            </>
                        ) : (
                            'Sign In'
                        )}
                    </button>
                    {/* Login Attempts Warning */}
                    {loginAttempts > 0 && (
                        <div className="attempts-warning">
                            <small>
                                Failed attempts: {loginAttempts}/3
                                {loginAttempts >= 2 && ' - Careful! One more attempt might lock your account.'}
                            </small>
                        </div>
                    )}
                </form>
                {/* Footer */}
                <div className="auth-footer">
                    <p className="security-note">
                        <FaLock /> Secure login with encrypted connection
                    </p>
                </div>
            </div>

            {/* Background Animation */}
            <div className="auth-background">
                <div className="shape shape-1"></div>
                <div className="shape shape-2"></div>
                <div className="shape shape-3"></div>
            </div>
        </div>
    );
};

export default Login;