import React, { useEffect, useState } from "react";
import axios from "axios";
import API_BASE_URL from "../../../../app/apiroutes";

import {
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Typography,
    Chip,
    CircularProgress,
    Button,
    Modal,
    Box,
    TextField
} from "@mui/material";

function CustomerList() {

    const [customers, setCustomers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [open, setOpen] = useState(false);
    const [selectedCustomer, setSelectedCustomer] = useState(null);

    const [formData, setFormData] = useState({
        first_name: "",
        last_name: "",
        email: "",
        phone: ""
    });

    const fetchCustomers = async () => {
        try {
            const token = localStorage.getItem('adminToken');
            if (!token) {
                throw new Error('Unauthorized. Please login again.');
            }
            const response = await axios.get(`${API_BASE_URL}/api/customers`, {
                headers: {
                    Authorization: `Bearer ${token}`
                }
            });
            setCustomers(response.data.customers);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleEdit = (customer) => {
        setSelectedCustomer(customer);

        setFormData({
            first_name: customer.first_name,
            last_name: customer.last_name,
            email: customer.email || "",
            phone: customer.phone
        });

        setOpen(true);
    };

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleUpdate = async () => {
        try {

            const token = localStorage.getItem("adminToken");

            await axios.put(
                `${API_BASE_URL}/api/customers/${selectedCustomer.id}`,
                formData,
                {
                    headers: {
                        Authorization: `Bearer ${token}`
                    }
                }
            );

            setOpen(false);

            fetchCustomers(); // reload table

        } catch (error) {
            console.error(error);
        }
    };

    const toggleStatus = async (customer) => {
        try {
            const token = localStorage.getItem("adminToken");
            const newStatus = customer.status === 1 ? 0 : 1;

            await axios.patch(
                `${API_BASE_URL}/api/customers/${customer.id}/status`,
                { status: newStatus },
                {
                    headers: {
                        Authorization: `Bearer ${token}`
                    }
                }
            );
            fetchCustomers();

        } catch (error) {
            console.error(error);
        }
    };
    useEffect(() => {
        fetchCustomers();
    }, []);

    return (
        <div className="container mt-4">

            <Typography variant="h5" gutterBottom>
                Customer List
            </Typography>

            {loading ? (
                <div className="text-center">
                    <CircularProgress />
                </div>
            ) : (
                <>
                    <TableContainer component={Paper}>

                        <Table>

                            <TableHead>

                                <TableRow>

                                    <TableCell>ID</TableCell>
                                    <TableCell>Name</TableCell>
                                    <TableCell>Email</TableCell>
                                    <TableCell>Phone</TableCell>
                                    <TableCell>Status</TableCell>
                                    <TableCell>Created</TableCell>
                                    <TableCell>Option</TableCell>
                                </TableRow>

                            </TableHead>

                            <TableBody>

                                {customers.lenght === 0 ? (

                                    <TableRow>
                                        <TableCell colSpan={6} align="center">
                                            No Customers Found
                                        </TableCell>
                                    </TableRow>

                                ) : (

                                    customers.map((customer) => (

                                        <TableRow key={customer.id} hover>

                                            <TableCell>{customer.id}</TableCell>

                                            <TableCell>
                                                {customer.first_name} {customer.last_name}
                                            </TableCell>

                                            <TableCell>
                                                {customer.email || "-"}
                                            </TableCell>

                                            <TableCell>
                                                {customer.phone}
                                            </TableCell>

                                            <TableCell>

                                                <Button
                                                    variant="contained"
                                                    size="small"
                                                    color={customer.status === 1 ? "success" : "error"}
                                                    onClick={() => toggleStatus(customer)}
                                                >
                                                    {customer.status === 1 ? "Active" : "Inactive"}
                                                </Button>

                                            </TableCell>

                                            <TableCell>
                                                {new Date(customer.created_at).toLocaleDateString()}
                                            </TableCell>
                                            <TableCell>
                                                <Button
                                                    variant="contained"
                                                    size="small"
                                                    onClick={() => handleEdit(customer)}
                                                >
                                                    Edit
                                                </Button>
                                            </TableCell>
                                        </TableRow>

                                    ))

                                )}

                            </TableBody>

                        </Table>

                    </TableContainer>
                    <Modal open={open} onClose={() => setOpen(false)}>

                        <Box
                            sx={{
                                position: "absolute",
                                top: "50%",
                                left: "50%",
                                transform: "translate(-50%, -50%)",
                                width: 400,
                                bgcolor: "background.paper",
                                p: 4,
                                borderRadius: 2
                            }}
                        >

                            <Typography variant="h6" mb={2}>
                                Edit Customer
                            </Typography>

                            <TextField
                                fullWidth
                                label="First Name"
                                name="first_name"
                                value={formData.first_name}
                                onChange={handleChange}
                                margin="normal"
                            />

                            <TextField
                                fullWidth
                                label="Last Name"
                                name="last_name"
                                value={formData.last_name}
                                onChange={handleChange}
                                margin="normal"
                            />

                            <TextField
                                fullWidth
                                label="Email"
                                name="email"
                                value={formData.email}
                                onChange={handleChange}
                                margin="normal"
                            />

                            <TextField
                                fullWidth
                                label="Phone"
                                name="phone"
                                value={formData.phone}
                                onChange={handleChange}
                                margin="normal"
                            />

                            <Button
                                variant="contained"
                                fullWidth
                                sx={{ mt: 2 }}
                                onClick={handleUpdate}
                            >
                                Update
                            </Button>

                        </Box>

                    </Modal>
                </>
            )}

        </div>
    );
}

export default CustomerList;