import React from "react";
import { Box, Container, Typography, Button } from "@mui/material";
import image from "../../../../assets/webheader.png";
import { useNavigate } from "react-router-dom";

const Slider = () => {
    const navigate = useNavigate();
  return (
    <Box
      sx={{
        position: "relative",
        width: "100%",
        height: 246,
        maxHeight: 246,
        overflow: "hidden"
      }}
    >
      {/* IMAGE */}
      <Box
        component="img"
        src={image}
        alt="Ujjain Tour"
        sx={{
          width: "100%",
          height: "100%",
          objectFit: "cover", // cover scales width to fill container
          display: "block"
        }}
      />

      {/* OVERLAY */}
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          background: "rgba(0,0,0,0.25)" // subtle overlay
        }}
      />

      {/* CONTENT */}
      <Container
        sx={{
          position: "absolute",
          inset: 0,
          zIndex: 2,
          display: "flex",
          alignItems: "center"
        }}
      >
        <Box>
          <Typography
            sx={{
              color: "#fff",
              fontWeight: 700,
              mb: 1,
              fontSize: { xs: "1.4rem", sm: "1.8rem", md: "2rem" }
            }}
          >
            Explore Ujjain with Us
          </Typography>

          <Typography
            sx={{
              color: "#e5e7eb",
              maxWidth: 520,
              mb: 2,
              fontSize: { xs: "0.9rem", sm: "1rem" }
            }}
          >
            Trusted travel partner for spiritual and holiday tours in Ujjain.
          </Typography>

          <Button
            variant="contained"
            size="medium"
            sx={{
              backgroundColor: "#ff9800",
              color: "#000",
              fontWeight: 600,
              px: 3,
              "&:hover": { backgroundColor: "#fb8c00" }
            }}
            onClick={()=>navigate(`/trips`)}
          >
            Book Your Trip
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default Slider;
