import React, { createContext, useState, useContext, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('adminToken');
    const userData = localStorage.getItem('adminUser');
    if (token && userData) {
      setUser(JSON.parse(userData));
    }
    setLoading(false);
  }, []);

  const login = async (email, password) => {
    // In a real app, this would be an API call
    const response = await mockLoginAPI(email, password);
    
    if (response.success) {
      localStorage.setItem('adminToken', response.token);
      localStorage.setItem('adminUser', JSON.stringify(response.user));
      setUser(response.user);
      return { success: true };
    }
    
    return { success: false, error: response.error };
  };
  
  const logout = () => {
    localStorage.removeItem('adminToken');
    localStorage.removeItem('adminUser');
    setUser(null);
    window.location.href = '/admin/login';
  };

   const mockLoginAPI = (email, password) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const demoCredentials = [
          { email: 'admin@ecommerce.com', password: 'admin123' },
          { email: 'manager@ecommerce.com', password: 'manager123' },
          { email: 'support@ecommerce.com', password: 'support123' }
        ];

        const validUser = demoCredentials.find(
          user => user.email === email && user.password === password
        );

        if (validUser) {
          resolve({
            success: true,
            token: `mock-jwt-token-${Date.now()}`,
            user: {
              id: Date.now(),
              name: email.split('@')[0],
              email: email,
              role: email.includes('admin') ? 'super-admin' : 
                     email.includes('manager') ? 'manager' : 'support',
              avatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(email.split('@')[0])}&background=3498db&color=fff`
            }
          });
        } else {
          resolve({
            success: false,
            error: 'Invalid credentials'
          });
        }
      }, 1000);
    });
  };

  
  const value = {
    user,
    loading,
    login,
    logout,
    isAuthenticated: !!user
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};