import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Toolbar,
  Typography,
  Box
} from '@mui/material';
import {
  Dashboard,
  Add,
  ListAlt
} from '@mui/icons-material';

const menuItems = [
  { path: '/admin/dashboard', label: 'Dashboard', icon: <Dashboard /> },
  { path: '/admin/add-new-tour', label: 'Add New Tour', icon: <Add /> },
  { path: '/admin/tour-list', label: 'Tour List', icon: <ListAlt /> },
  { path: '/admin/customer-list', label: 'Customer List', icon: <ListAlt /> },
  { path: '/admin/pending-order-list', label: 'Pending Orders', icon: <ListAlt /> },
  { path: '/admin/confirm-order-list', label: 'Confirm Orders', icon: <ListAlt /> },
  { path: '/admin/pickup-order-list', label: 'Pickup Orders', icon: <ListAlt /> },
  { path: '/admin/complate-order-list', label: 'Complate Orders', icon: <ListAlt /> },
  { path: '/admin/refund-order-list', label: 'Refund Orders', icon: <ListAlt /> },
  { path: '/admin/cancel-order-list', label: 'Cancel Orders', icon: <ListAlt /> },
  { path: '/admin/gst-settings', label: 'GST Setting', icon: <ListAlt /> },
  { path: '/admin/business-settings', label: 'Business Setting', icon: <ListAlt /> },
];

const Sidebar = ({ mobileOpen, onClose, drawerWidth }) => {
  const location = useLocation();

  const drawerContent = (
    <Box>
      <Toolbar>
        <Typography variant="h6" color="primary">
          Admin Panel
        </Typography>
      </Toolbar>

      <List>
        {menuItems.map((item) => (
          <ListItemButton
            key={item.path}
            component={Link}
            to={item.path}
            selected={location.pathname === item.path}
            onClick={onClose} // 👈 auto close on mobile
          >
            <ListItemIcon>{item.icon}</ListItemIcon>
            <ListItemText primary={item.label} />
          </ListItemButton>
        ))}
      </List>
    </Box>
  );

  return (
    <>
      {/* MOBILE DRAWER */}
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={onClose}
        ModalProps={{ keepMounted: true }} // 🔥 performance fix
        sx={{
          display: { xs: 'block', sm: 'none' },
          '& .MuiDrawer-paper': {
            width: drawerWidth
          }
        }}
      >
        {drawerContent}
      </Drawer>

      {/* DESKTOP DRAWER */}
      <Drawer
        variant="permanent"
        open
        sx={{
          display: { xs: 'none', sm: 'block' },
          '& .MuiDrawer-paper': {
            width: drawerWidth,
            boxSizing: 'border-box'
          }
        }}
      >
        {drawerContent}
      </Drawer>
    </>
  );
};

export default Sidebar;
